df = pd.read_csv('/app/benchmark/data.csv')

# Split composers to count individual wins accurately
# Some composers are separated by commas
def get_individual_composers(composer_string):
    return [c.strip() for c in composer_string.split(',')]

# Expand dataset to have one row per individual composer per film
records = []
for idx, row in df.iterrows():
    composers = get_individual_composers(row['Composer'])
    for c in composers:
        records.append({
            'Year': row['Year'],
            'Film': row['Film'],
            'Composer': c,
            'Original_Composer_String': row['Composer']
        })

df_expanded = pd.DataFrame(records)

# KPIs
total_unique_composers = df_expanded['Composer'].nunique()
composer_win_counts = df_expanded['Composer'].value_counts()
max_wins = composer_win_counts.max()
top_composer = composer_win_counts.idxmax()

# Repeat Winner Rate
