    for c in year_composers:
        if c in seen_composers:
            is_repeat = True
        seen_composers.add(c)
    if is_repeat:
        repeat_ceremonies += 1

repeat_winner_rate = repeat_ceremonies / len(df)

# Decade with Most Unique Winners
df['Decade'] = (df['Year'] // 10) * 10
df_expanded['Decade'] = (df_expanded['Year'] // 10) * 10

decade_unique_composers = df_expanded.groupby('Decade')['Composer'].nunique()
most_diverse_decade = decade_unique_composers.idxmax()

# Eras
def get_era(year):
    if 1934 <= year <= 1959:
        return 'Golden Age (1934-1959)'
    elif 1960 <= year <= 1979:
        return 'Silver Age (1960-1979)'
    elif 1980 <= year <= 1999:
        return 'Modern Age (1980-1999)'
    else:
        return 'Contemporary (2000-2026)'

df['Era'] = df['Year'].apply(get_era)
df_expanded['Era'] = df_expanded['Year'].apply(get_era)

# Charts
plt.style.use('ggplot')
def fig_to_base64(fig):
    buf = BytesIO()
    fig.savefig(buf, format='png', bbox_inches='tight')
    buf.seek(0)
    img_str = base64.b64encode(buf.read()).decode('utf-8')
    plt.close(fig)
    return img_str

# Chart 1: Top Composers
