# Chart 2: Wins by Decade
fig2, ax2 = plt.subplots(figsize=(10, 6))
decade_counts = df['Decade'].value_counts().sort_index()
# To show diversity, let's plot total awards vs unique winners per decade
decade_stats = pd.DataFrame({
    'Total Awards': df.groupby('Decade')['Year'].count(),
    'Unique Composers': decade_unique_composers
})
